/* Deterministic rendering of the playground's original poses and CSS easing. */
(() => {
  const exportImages = ["data:image/svg+xml;base64,", "data:image/svg+xml;base64,", "data:image/svg+xml;base64,", "data:image/svg+xml;base64,", "data:image/svg+xml;base64,"].map(src=>{const img=new Image();img.src=src;return img;});
  const $ = id => document.getElementById(id);
  function easing(x, tight) {
    const [x1,y1,x2,y2] = tight > 70 ? [.18,.92,.22,1] : [.45,0,.25,1];
    const bez = (t,a,b) => 3*(1-t)*(1-t)*t*a + 3*(1-t)*t*t*b + t*t*t;
    let lo=0,hi=1;
    for(let i=0;i<30;i++){const mid=(lo+hi)/2;if(bez(mid,x1,x2)<x)lo=mid;else hi=mid;}
    return bez((lo+hi)/2,y1,y2);
  }
  const table = Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=(n&1)?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
  function crc(bytes){let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
  function header(size){const bytes=new Uint8Array(size);return {bytes,view:new DataView(bytes.buffer)};}
  function zipEntry(name,data,offset){
    const n=new TextEncoder().encode(name),c=crc(data),a=header(30),b=header(46);
    a.view.setUint32(0,0x04034b50,true);a.view.setUint16(4,20,true);a.view.setUint32(14,c,true);a.view.setUint32(18,data.length,true);a.view.setUint32(22,data.length,true);a.view.setUint16(26,n.length,true);
    b.view.setUint32(0,0x02014b50,true);b.view.setUint16(4,20,true);b.view.setUint16(6,20,true);b.view.setUint32(16,c,true);b.view.setUint32(20,data.length,true);b.view.setUint32(24,data.length,true);b.view.setUint16(28,n.length,true);b.view.setUint32(42,offset,true);
    return {local:[a.bytes,n,data],central:[b.bytes,n],length:30+n.length+data.length};
  }
  $('exportSequence').onclick=async()=>{
    const button=$('exportSequence'),status=$('exportStatus');button.disabled=true;
    const selected=mode,bpm=+$('bpm').value,tight=+$('tightness').value,fps=+$('exportFps').value,width=+$('exportSize').value,height=width===1080?1080:width*9/16,bg='transparent';
    const steps=[...sequences[selected]],beat=60/bpm,motion=beat*(.92-tight/100*.58),duration=steps.length*beat,count=Math.ceil(duration*fps);
    try{
      status.textContent='로고 준비 중…';
      await Promise.all(exportImages.map(img=>img.decode()));
      const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
      const ctx=canvas.getContext('2d'),cell=Math.min(width*.84/(7*.9309+1),height*.7/(2*.9309+1)),step=cell*.9309,ox=(width-(7*step+cell))/2,oy=(height-(2*step+cell))/2;
      const locals=[],centrals=[];let offset=0,centralSize=0;
      const add=(name,data)=>{const entry=zipEntry(name,data,offset);locals.push(...entry.local);centrals.push(...entry.central);offset+=entry.length;centralSize+=entry.central.reduce((n,a)=>n+a.length,0);};
      for(let frame=0;frame<count;frame++){
        const t=frame/fps,index=Math.min(Math.floor(t/beat),steps.length-1),phase=Math.min(1,(t-index*beat)/motion),mix=easing(phase,tight),from=layouts[steps[index===0?steps.length-1:index-1]],to=layouts[steps[index]];
        ctx.clearRect(0,0,width,height);if(bg==='white'){ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);}
        exportImages.forEach((img,i)=>{const x=from[i][0]+(to[i][0]-from[i][0])*mix,y=from[i][1]+(to[i][1]-from[i][1])*mix;ctx.drawImage(img,ox+x*step,oy+y*step,cell*img.naturalWidth/img.naturalHeight,cell);});
        const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 생성 실패');
        add(`frames/craft-lab_${String(frame).padStart(5,'0')}.png`,new Uint8Array(await blob.arrayBuffer()));
        if(frame%5===0){status.textContent=`${frame+1} / ${count} 프레임 생성 중…`;await new Promise(resolve=>setTimeout(resolve,0));}
      }
      add('settings.json',new TextEncoder().encode(JSON.stringify({format:selected,bpm,tightness:tight,fps,width,height,background:bg,frames:count,motionDurationSeconds:duration,sequenceDurationSeconds:count/fps},null,2)));
      add('README.txt',new TextEncoder().encode(`CRAFT LAB PNG sequence\nImport frames/craft-lab_00000.png as an image sequence.\nSet interpretation frame rate to ${fps} fps.\n${count} frames, ${width} x ${height}, ${bg} background.\nSource: https://craft-lab-motion.vercel.app/\n`));
      const end=header(22);end.view.setUint32(0,0x06054b50,true);end.view.setUint16(8,count+2,true);end.view.setUint16(10,count+2,true);end.view.setUint32(12,centralSize,true);end.view.setUint32(16,offset,true);
      downloadBlob(new Blob([...locals,...centrals,end.bytes],{type:'application/zip'}),`craft-lab-${selected}-${fps}fps.zip`);
      status.textContent=`완료 · ${count}프레임 · ${fps}fps · ${(count/fps).toFixed(2)}초`;
    }catch(error){status.textContent=`저장 실패: ${error.message}. 크기나 프레임 수를 낮춰 다시 시도해 주세요.`;}
    finally{button.disabled=false;}
  };
})();
